import{_ as r,C as t,o as n,c as o,j as e,a as i,E as p,a2 as g}from"./chunks/framework.XXezeKOl.js";const b=JSON.parse('{"title":"12 周学习计划","description":"每周 8 到 10 小时，12 周从环境搭建走到毕业项目，每周都有目标、必读文章、作业和自检问题。","frontmatter":{"title":"12 周学习计划","description":"每周 8 到 10 小时，12 周从环境搭建走到毕业项目，每周都有目标、必读文章、作业和自检问题。"},"headers":[],"relativePath":"roadmap/12-weeks.md","filePath":"roadmap/12-weeks.md","lastUpdated":null}'),s={name:"roadmap/12-weeks.md"};function h(u,a,d,c,f,m){const l=t("ProgressTracker");return n(),o("div",null,[a[0]||(a[0]=e("h1",{id:"_12-周学习计划",tabindex:"-1"},[i("12 周学习计划 "),e("a",{class:"header-anchor",href:"#_12-周学习计划","aria-label":'Permalink to "12 周学习计划"'},"​")],-1)),a[1]||(a[1]=e("p",null,[i("这份计划适合有一点编程基础、希望按固定节奏学习的同学。每周投入 8 到 10 小时：大约一半时间读文章，一半时间写代码。完全零基础的同学建议先看 "),e("a",{href:"/roadmap/beginner"},"零基础入门路径"),i("，在第 1-2 周多花一倍时间。")],-1)),a[2]||(a[2]=e("p",null,"下面的进度表会保存在你的浏览器本地，完成一周就勾一周。",-1)),p(l,{weeks:["环境与 Python 基础","HTTP、异步与第一次调用","大模型原理","提示词工程","Tool Calling","Agent 循环","上下文工程与记忆","RAG 知识库","MCP 与框架","多 Agent 系统","评估与可观测性","安全、部署与毕业项目"]}),a[3]||(a[3]=g(`<div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段1 基础准备      阶段2 大模型与提示词   阶段3 Tool Calling   阶段4 上下文/记忆/RAG/MCP   阶段5 多 Agent 与生产化</span></span>
<span class="line"><span>第 1-2 周           第 3-4 周              与 Agent 循环        第 7-9 周                  第 10-12 周</span></span>
<span class="line"><span>                                           第 5-6 周</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">使用建议</p><ul><li>作业比阅读重要。读完没做作业，等于这周没学。</li><li>自检问题请先合上文章、用自己的话回答，答不上来再回去看。</li><li>进度落后一周很正常，但不要跳过阶段 3，它是后面所有内容的基础。</li></ul></div><h2 id="阶段-1-基础准备" tabindex="-1">阶段 1：基础准备 <a class="header-anchor" href="#阶段-1-基础准备" aria-label="Permalink to &quot;阶段 1：基础准备&quot;">​</a></h2><h3 id="第-1-周-环境与-python-基础" tabindex="-1">第 1 周：环境与 Python 基础 <a class="header-anchor" href="#第-1-周-环境与-python-基础" aria-label="Permalink to &quot;第 1 周：环境与 Python 基础&quot;">​</a></h3><p>本周目标：搭好开发环境，掌握 Agent 开发中最常用的 Python 写法，并对 Agent 建立正确的第一印象。</p><p>必读文章：</p><ul><li><a href="/guide/00-intro/what-is-agent">Agent 到底是什么</a></li><li><a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a></li><li><a href="/guide/00-intro/how-to-learn">如何使用本站学习</a></li><li><a href="/guide/01-programming/dev-env">开发环境：Python / Go / Java</a></li><li><a href="/guide/01-programming/python-essentials">Agent 开发必备 Python</a></li><li><a href="/guide/01-programming/data-validation">数据校验：pydantic / struct tag / record</a></li></ul><p>本周作业：</p><ol><li>安装 Python 和一个包管理工具，创建项目目录和虚拟环境。</li><li>用 pydantic 定义一个 <code>Task</code> 模型（标题、优先级、截止日期），写函数把 JSON 字符串解析成 <code>Task</code> 列表，对非法数据给出友好报错。</li><li>把代码提交到自己的 Git 仓库，后面 11 周都在这个仓库里迭代。</li></ol><p>自检问题：</p><ul><li>Agent 和普通聊天机器人最本质的区别是什么？</li><li>为什么不能把 API Key 写在代码里？你用什么方式管理它？</li><li>pydantic 校验失败时会发生什么？你会如何处理？</li></ul><h3 id="第-2-周-http、异步与第一次调用" tabindex="-1">第 2 周：HTTP、异步与第一次调用 <a class="header-anchor" href="#第-2-周-http、异步与第一次调用" aria-label="Permalink to &quot;第 2 周：HTTP、异步与第一次调用&quot;">​</a></h3><p>本周目标：理解 HTTP 和流式输出，完成第一次大模型 API 调用。</p><p>必读文章：</p><ul><li><a href="/guide/01-programming/http-json">HTTP、JSON 与 REST API</a></li><li><a href="/guide/01-programming/async">异步与并发编程</a></li><li><a href="/guide/01-programming/streaming-sse">流式输出与 SSE</a></li><li><a href="/guide/03-llm-api/first-call">第一次调用大模型</a></li><li><a href="/guide/03-llm-api/providers">主流模型厂商 API 对比</a></li></ul><p>本周作业：</p><ol><li>用官方 SDK 调用一次大模型，再用原始 HTTP 请求（<code>httpx</code>）完成同样的调用，对比两者的请求体。</li><li>用 <code>asyncio.gather</code> 并发发出 3 个问题，记录总耗时，与串行调用对比。</li></ol><p>自检问题：</p><ul><li>一次大模型 API 请求的 Body 里通常包含哪些字段？</li><li>SSE 和普通 HTTP 响应有什么区别？为什么大模型应用常用它？</li><li>什么场景适合用异步？异步一定比同步快吗？</li></ul><h2 id="阶段-2-大模型与提示词" tabindex="-1">阶段 2：大模型与提示词 <a class="header-anchor" href="#阶段-2-大模型与提示词" aria-label="Permalink to &quot;阶段 2：大模型与提示词&quot;">​</a></h2><h3 id="第-3-周-大模型原理" tabindex="-1">第 3 周：大模型原理 <a class="header-anchor" href="#第-3-周-大模型原理" aria-label="Permalink to &quot;第 3 周：大模型原理&quot;">​</a></h3><p>本周目标：建立对模型工作方式的直觉，理解 Token、上下文窗口和采样参数，能做出一个多轮对话程序。</p><p>必读文章：</p><ul><li><a href="/guide/02-llm-basics/transformer">Transformer 的直觉理解</a></li><li><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></li><li><a href="/guide/02-llm-basics/sampling">采样参数：temperature、top_p</a></li><li><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></li><li><a href="/guide/02-llm-basics/choosing-models">如何选择模型</a></li><li><a href="/guide/03-llm-api/multi-turn">多轮对话与消息结构</a></li><li><a href="/guide/03-llm-api/streaming">流式响应实战</a></li><li><a href="/guide/03-llm-api/cost-errors">计费、限流与错误重试</a></li></ul><p>本周作业：完成 <a href="/projects/01-cli-chat">01 命令行聊天助手</a>：支持多轮对话、流式输出、遇到限流自动重试，并在每轮结束后打印本轮 Token 用量。</p><p>自检问题：</p><ul><li>为什么说&quot;模型没有记忆&quot;？多轮对话是怎么实现的？</li><li>把 temperature 设为 0，输出就一定完全相同吗？</li><li>对话越来越长时会出现什么问题？你的聊天助手如何应对？</li></ul><h3 id="第-4-周-提示词工程" tabindex="-1">第 4 周：提示词工程 <a class="header-anchor" href="#第-4-周-提示词工程" aria-label="Permalink to &quot;第 4 周：提示词工程&quot;">​</a></h3><p>本周目标：掌握写提示词的基本原则，能让模型稳定输出可被程序解析的结构化结果。</p><p>必读文章：</p><ul><li><a href="/guide/04-prompt/basics">提示词基本原则</a></li><li><a href="/guide/04-prompt/system-prompt">系统提示词与角色设计</a></li><li><a href="/guide/04-prompt/few-shot-cot">Few-shot 与思维链</a></li><li><a href="/guide/04-prompt/structured-output">结构化输出与 JSON Schema</a></li><li><a href="/guide/04-prompt/prompt-management">提示词版本管理与测试</a></li><li>选读论文：<a href="/papers/chain-of-thought">Chain-of-Thought</a></li></ul><p>本周作业：</p><ol><li>写一个&quot;简历信息提取器&quot;：输入一段简历文本，输出符合 JSON Schema 的结构化数据（姓名、技能列表、工作经历）。</li><li>准备 10 份不同风格的简历样例，写脚本批量运行并统计解析成功率。修改提示词后重新运行，比较结果。</li></ol><p>自检问题：</p><ul><li>好的系统提示词通常包含哪几部分？</li><li>Few-shot 示例选得不好会带来什么问题？</li><li>为什么提示词需要像代码一样做版本管理和回归测试？</li></ul><h2 id="阶段-3-tool-calling-与-agent-循环" tabindex="-1">阶段 3：Tool Calling 与 Agent 循环 <a class="header-anchor" href="#阶段-3-tool-calling-与-agent-循环" aria-label="Permalink to &quot;阶段 3：Tool Calling 与 Agent 循环&quot;">​</a></h2><h3 id="第-5-周-tool-calling" tabindex="-1">第 5 周：Tool Calling <a class="header-anchor" href="#第-5-周-tool-calling" aria-label="Permalink to &quot;第 5 周：Tool Calling&quot;">​</a></h3><p>本周目标：理解工具调用的完整流程，能为模型设计好用的工具并处理各种异常。</p><p>必读文章：</p><ul><li><a href="/guide/05-tool-calling/concept">工具调用原理</a></li><li><a href="/guide/05-tool-calling/first-tool">实现第一个工具</a></li><li><a href="/guide/05-tool-calling/tool-design">工具设计原则</a></li><li><a href="/guide/05-tool-calling/parallel-tools">并行工具调用</a></li><li><a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a></li><li>选读论文：<a href="/papers/toolformer">Toolformer</a></li></ul><p>本周作业：完成 <a href="/projects/02-tool-agent">02 天气日程工具 Agent</a>。至少实现 3 个工具（查天气、查日程、创建日程），并故意让其中一个工具随机报错，观察模型如何应对。</p><p>自检问题：</p><ul><li>在 Tool Calling 中，模型做了什么，你的代码做了什么？</li><li>工具描述写得含糊会导致哪些问题？</li><li>模型一次返回多个工具调用时，结果要如何对应回去？</li></ul><h3 id="第-6-周-agent-循环" tabindex="-1">第 6 周：Agent 循环 <a class="header-anchor" href="#第-6-周-agent-循环" aria-label="Permalink to &quot;第 6 周：Agent 循环&quot;">​</a></h3><p>本周目标：不使用任何框架，亲手写出一个完整的 Agent 循环，并理解几种主流的控制模式。</p><p>必读文章：</p><ul><li><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></li><li><a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a></li><li><a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a></li><li><a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a></li><li><a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li><li>选读论文：<a href="/papers/react">ReAct</a>、<a href="/papers/reflexion">Reflexion</a></li></ul><p>本周作业：完成 <a href="/projects/03-react-agent">03 手写 ReAct Agent</a>。要求：最大步数限制、Token 预算限制、每一步的思考和工具调用都打印出来。再给它加一个&quot;完成前自我检查&quot;的 Reflection 步骤，对比加之前和加之后的效果。</p><p>自检问题：</p><ul><li>画出 Agent 循环的流程图，并指出循环在什么条件下结束。</li><li>ReAct 和 Plan-and-Execute 分别适合什么样的任务？</li><li>如果 Agent 反复调用同一个工具陷入死循环，你有哪些办法？</li></ul><h2 id="阶段-4-上下文、记忆、rag-与-mcp" tabindex="-1">阶段 4：上下文、记忆、RAG 与 MCP <a class="header-anchor" href="#阶段-4-上下文、记忆、rag-与-mcp" aria-label="Permalink to &quot;阶段 4：上下文、记忆、RAG 与 MCP&quot;">​</a></h2><h3 id="第-7-周-上下文工程与记忆" tabindex="-1">第 7 周：上下文工程与记忆 <a class="header-anchor" href="#第-7-周-上下文工程与记忆" aria-label="Permalink to &quot;第 7 周：上下文工程与记忆&quot;">​</a></h3><p>本周目标：理解上下文是 Agent 最稀缺的资源，掌握窗口管理、压缩和记忆的基本方案。</p><p>必读文章：</p><ul><li><a href="/guide/07-context-engineering/overview">什么是上下文工程</a></li><li><a href="/guide/07-context-engineering/window-management">上下文窗口管理</a></li><li><a href="/guide/07-context-engineering/compression">压缩与摘要</a></li><li><a href="/guide/07-context-engineering/prompt-caching">Prompt Caching</a></li><li><a href="/guide/08-memory/memory-types">记忆的分类</a></li><li><a href="/guide/08-memory/short-term">短期记忆与会话管理</a></li><li><a href="/guide/08-memory/long-term">长期记忆与用户画像</a></li><li><a href="/guide/08-memory/memory-strategy">记忆读写策略与方案对比</a></li></ul><p>本周作业：给第 6 周的 Agent 加上两种能力：当上下文超过阈值时自动摘要早期对话；把&quot;用户偏好&quot;写入一个本地 JSON 文件，下次启动时读取并放入系统提示词。</p><p>自检问题：</p><ul><li>上下文工程和提示词工程有什么区别？</li><li>摘要压缩可能丢失什么信息？如何降低风险？</li><li>长期记忆什么时候写入、什么时候读取？写错了怎么办？</li></ul><h3 id="第-8-周-rag-知识库" tabindex="-1">第 8 周：RAG 知识库 <a class="header-anchor" href="#第-8-周-rag-知识库" aria-label="Permalink to &quot;第 8 周：RAG 知识库&quot;">​</a></h3><p>本周目标：从零搭建一个 RAG 系统，理解检索质量对最终答案的决定性影响。</p><p>必读文章：</p><ul><li><a href="/guide/02-llm-basics/embeddings">Embedding 与向量语义</a></li><li><a href="/guide/09-rag/overview">RAG 全景</a></li><li><a href="/guide/09-rag/chunking">文档解析与切分</a></li><li><a href="/guide/09-rag/vector-db">向量数据库</a></li><li><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></li><li><a href="/guide/09-rag/advanced-rag">GraphRAG 与 Agentic RAG</a></li><li><a href="/guide/09-rag/rag-eval">RAG 评估</a></li><li>选读论文：<a href="/papers/rag">RAG 原始论文</a></li></ul><p>本周作业：完成 <a href="/projects/04-pdf-rag">04 个人 PDF 知识库</a>。准备 20 个问题和标准答案，分别统计&quot;只用向量检索&quot;和&quot;向量检索加重排&quot;两种方案的命中率。</p><p>自检问题：</p><ul><li>RAG 的离线和在线两条链路分别做什么？</li><li>切分块大小如何影响检索效果？</li><li>答案错了，你怎么判断是检索的问题还是生成的问题？</li></ul><h3 id="第-9-周-mcp-与框架" tabindex="-1">第 9 周：MCP 与框架 <a class="header-anchor" href="#第-9-周-mcp-与框架" aria-label="Permalink to &quot;第 9 周：MCP 与框架&quot;">​</a></h3><p>本周目标：掌握 MCP 协议，了解主流框架的定位，能判断什么时候该用框架。</p><p>必读文章：</p><ul><li><a href="/guide/10-mcp/mcp-overview">MCP 架构与核心概念</a></li><li><a href="/guide/10-mcp/mcp-server">开发一个 MCP Server</a></li><li><a href="/guide/10-mcp/mcp-client">在应用中接入 MCP</a></li><li><a href="/guide/10-mcp/a2a">A2A：Agent 之间的协议</a></li><li><a href="/guide/11-frameworks/overview">框架全景与选型</a></li><li><a href="/guide/11-frameworks/langgraph">LangGraph</a></li><li><a href="/guide/11-frameworks/agent-sdks">Claude Agent SDK 与 OpenAI Agents SDK</a></li><li>按语言选读：<a href="/guide/11-frameworks/go-eino">Go：Eino 与 langchaingo</a> 或 <a href="/guide/11-frameworks/java-spring-ai">Java：Spring AI 与 LangChain4j</a></li></ul><p>本周作业：完成 <a href="/projects/05-mcp-server">05 开发自己的 MCP Server</a>，把第 8 周的知识库检索包装成一个 MCP 工具，并在一个支持 MCP 的客户端里调用它。再用 LangGraph 把第 6 周的 Agent 重写一遍，记录代码量和可读性的变化。</p><p>自检问题：</p><ul><li>MCP 解决了什么问题？Host、Client、Server 分别是什么？</li><li>MCP 的 Tools、Resources、Prompts 有什么区别？</li><li>你的项目里用框架的收益和代价各是什么？</li></ul><h2 id="阶段-5-多-agent-与生产化" tabindex="-1">阶段 5：多 Agent 与生产化 <a class="header-anchor" href="#阶段-5-多-agent-与生产化" aria-label="Permalink to &quot;阶段 5：多 Agent 与生产化&quot;">​</a></h2><h3 id="第-10-周-多-agent-系统" tabindex="-1">第 10 周：多 Agent 系统 <a class="header-anchor" href="#第-10-周-多-agent-系统" aria-label="Permalink to &quot;第 10 周：多 Agent 系统&quot;">​</a></h3><p>本周目标：理解多 Agent 的价值和代价，掌握常见的编排模式。</p><p>必读文章：</p><ul><li><a href="/guide/12-multi-agent/why-multi-agent">为什么需要多 Agent</a></li><li><a href="/guide/12-multi-agent/patterns">编排模式：主从、流水线、交接、辩论</a></li><li><a href="/guide/12-multi-agent/state-sharing">状态共享与通信</a></li><li><a href="/guide/12-multi-agent/pitfalls">多 Agent 的坑与成本控制</a></li><li><a href="/guide/13-coding-agent/coding-agents">Coding Agent 原理</a></li><li><a href="/guide/13-coding-agent/sandbox">沙箱与代码执行安全</a></li><li>选读论文：<a href="/papers/generative-agents">Generative Agents</a>、<a href="/papers/swe-agent">SWE-agent</a></li></ul><p>本周作业：完成 <a href="/projects/06-research-agent">06 网页研究员 Agent</a> 或 <a href="/projects/07-writing-team">07 多 Agent 写作团队</a>。对同一批任务分别跑单 Agent 和多 Agent 版本，记录质量、Token 消耗和耗时。</p><p>自检问题：</p><ul><li>什么样的任务值得拆成多个 Agent？什么样的任务不值得？</li><li>主从模式中，子 Agent 应该把什么信息交还给主 Agent？</li><li>多 Agent 系统最常见的失败原因有哪些？</li></ul><h3 id="第-11-周-评估与可观测性" tabindex="-1">第 11 周：评估与可观测性 <a class="header-anchor" href="#第-11-周-评估与可观测性" aria-label="Permalink to &quot;第 11 周：评估与可观测性&quot;">​</a></h3><p>本周目标：建立评估集和轨迹追踪，让每一次修改都能被量化。</p><p>必读文章：</p><ul><li><a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a></li><li><a href="/guide/14-evaluation/eval-design">评估集与指标设计</a></li><li><a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a></li><li><a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a></li><li><a href="/guide/14-evaluation/regression">回归测试与持续评估</a></li></ul><p>本周作业：为你最满意的一个项目建立至少 30 条用例的评估集，包含正常、边界和对抗用例；写一个 LLM-as-Judge 评分器，并抽 10 条与自己的人工评分对比；接入一个追踪工具，能看到每次请求的完整轨迹。</p><p>自检问题：</p><ul><li>为什么说没有评估集的 Agent 无法迭代？</li><li>LLM-as-Judge 有哪些已知偏差？如何缓解？</li><li>一条完整的 Agent 轨迹里应该记录哪些信息？</li></ul><h3 id="第-12-周-安全、部署与毕业项目" tabindex="-1">第 12 周：安全、部署与毕业项目 <a class="header-anchor" href="#第-12-周-安全、部署与毕业项目" aria-label="Permalink to &quot;第 12 周：安全、部署与毕业项目&quot;">​</a></h3><p>本周目标：掌握生产化的关键环节，交付一个完整的毕业项目。</p><p>必读文章：</p><ul><li><a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a></li><li><a href="/guide/15-production/permissions-hitl">权限控制与人在环路</a></li><li><a href="/guide/15-production/guardrails">护栏与内容安全</a></li><li><a href="/guide/15-production/cost-optimization">成本与延迟优化</a></li><li><a href="/guide/15-production/serving">服务化：FastAPI / Gin / Spring Boot</a></li><li><a href="/guide/15-production/deployment">部署、监控与运维</a></li></ul><p>本周作业：完成 <a href="/projects/10-enterprise-assistant">10 毕业项目：企业知识助手</a>。至少包含：RAG 检索、2 个以上工具、Prompt 注入防护、高风险操作人工确认、第 11 周的评估集和轨迹追踪、以 HTTP 服务形式部署。</p><p>自检问题：</p><ul><li>间接 Prompt 注入是怎么发生的？你的项目里有哪些入口？</li><li>哪些工具调用需要人工确认？依据是什么？</li><li>如果明天调用量翻 10 倍，成本和延迟会出现什么问题？你准备怎么办？</li></ul><h2 id="学完之后" tabindex="-1">学完之后 <a class="header-anchor" href="#学完之后" aria-label="Permalink to &quot;学完之后&quot;">​</a></h2><ul><li>用 <a href="/interview/">面试题</a> 检验自己的理解深度。</li><li>读完 <a href="/papers/">论文精读</a> 中的全部论文。</li><li>回头做 <a href="/projects/08-code-review">08 代码审查 Agent</a> 和 <a href="/projects/09-agent-workbench">09 全栈 Agent 工作台</a>，补齐没做的项目。</li><li>如果开始负责团队的 Agent 落地，继续看 <a href="/roadmap/architect">架构师路径</a>。</li></ul>`,96))])}const P=r(s,[["render",h]]);export{b as __pageData,P as default};
